{
  "narratives": [
    {
      "item_code": "S5_MEDIA",
      "title_raw": "가. 적절한(부적절한) 소화제",
      "start": "p2:L25",
      "end": "p2:L28"
    },
    {
      "item_code": "S5_SPECIFIC",
      "title_raw": "나. 화학물질로부터 생기는 특정 유해성",
      "start": "p3:L1",
      "end": "p3:L10"
    },
    {
      "item_code": "S5_FIREFIGHT",
      "title_raw": "다. 화재진압 시 착용할 보호구 및 예방조치",
      "start": "p3:L11",
      "end": "p3:L13"
    }
  ],
  "extras": [
    {
      "title_raw": "적절한 소화제",
      "reason": "필드없음",
      "statements": [
        {
          "key": "적절한 소화제",
          "value": "분말 소화약제, 이산화탄소, 물, 일반적인 포말",
          "line": "p2:L26"
        }
      ],
      "line": "p2:L26"
    },
    {
      "title_raw": "부적절한 소화제",
      "reason": "필드없음",
      "statements": [
        {
          "value": "자료없음",
          "line": "p2:L27"
        }
      ],
      "line": "p2:L27"
    },
    {
      "title_raw": "대형 화재 시",
      "reason": "필드없음",
      "statements": [
        {
          "value": "위험하지 않으면, 용기를 화재위험지역 밖으로 옮기시오.",
          "line": "p2:L28"
        }
      ],
      "line": "p2:L28"
    },
    {
      "title_raw": "열분해 생성물",
      "reason": "필드없음",
      "statements": [
        {
          "value": "할로겐화 화합물, 탄소산화물, 염화수소, 일산화탄소, 이산화탄소",
          "line": "p3:L3"
        }
      ],
      "line": "p3:L3"
    },
    {
      "title_raw": "화재 및 폭발위험",
      "reason": "필드없음",
      "statements": [
        {
          "value": "분진과 공기의 혼합물은 발화하거나 폭발할 수 있음",
          "line": "p3:L5"
        },
        {
          "value": "열, 스파크, 화염에 의해 점화할 수 있음",
          "line": "p3:L6"
        },
        {
          "value": "가열시 용기가 폭발할 수 있음",
          "line": "p3:L7"
        },
        {
          "value": "일부는 탈 수 있으나 쉽게 점화하지 않음",
          "line": "p3:L8"
        },
        {
          "value": "화재시 자극성, 독성 가스를 발생할 수 있음",
          "line": "p3:L9"
        },
        {
          "value": "물질의 흡입은 유해할 수 있음",
          "line": "p3:L10"
        }
      ],
      "line": "p3:L4"
    },
    {
      "title_raw": "소화수의 처분을 위해 도랑을 파서 가두고 물질이 흩어지지 않게 하시오.",
      "reason": "필드없음",
      "statements": [
        {
          "value": "소화수의 처분을 위해 도랑을 파서 가두고 물질이 흩어지지 않게 하시오.",
          "line": "p3:L12"
        }
      ],
      "line": "p3:L12"
    },
    {
      "title_raw": "위험하지 않다면 화재지역에서 용기를 옮기시오.",
      "reason": "필드없음",
      "statements": [
        {
          "value": "위험하지 않다면 화재지역에서 용기를 옮기시오.",
          "line": "p3:L13"
        }
      ],
      "line": "p3:L13"
    }
  ]
}

